#!/usr/bin/env python3
"""Mnemosyne job -005: label-6 CArnoldi SOLVE at prec 100.
Builds FLINT 3.1.2 from source (container is root), fetches and compiles
upstream Cext/powser_arnoldi.c (michaelmusty/Belyi, MIT), runs it on the
embedded p100 input (f64-certified, crosscheck-p100-receipt.json), ships
label6-out-p100.m back as gzip+base64 between MARKER FILE BEGIN/END.
Gates: build exit 0; solver exit 0; outfile nonempty Magma [* ... *] data.
The 10^(-88) residual gate is applied on the Mac side after decode.
"""
import subprocess as sp, sys, os, base64, gzip, time, urllib.request

PAYLOAD = ""

def run(cmd, **kw):
    t0 = time.time()
    r = sp.run(cmd, shell=True, capture_output=True, text=True, **kw)
    print(f"MARKER step [{cmd[:60]}] exit={r.returncode} {time.time()-t0:.0f}s", flush=True)
    if r.returncode != 0:
        print(r.stdout[-2000:]); print(r.stderr[-4000:], file=sys.stderr)
        sys.exit(1)
    return r

os.chdir("/tmp")
run("apt-get update -qq && apt-get install -y -qq build-essential libgmp-dev libmpfr-dev xz-utils > /dev/null")
urllib.request.urlretrieve(
    "https://github.com/flintlib/flint/releases/download/v3.1.2/flint-3.1.2.tar.xz",
    "flint.tar.xz")
run("tar xf flint.tar.xz")
run("cd flint-3.1.2 && ./configure --disable-static > cfg.log && make -j$(nproc) > make.log 2>&1 && make install > inst.log && ldconfig")
urllib.request.urlretrieve(
    "https://raw.githubusercontent.com/michaelmusty/Belyi/master/Cext/powser_arnoldi.c",
    "powser_arnoldi.c")
run("gcc -O3 -o powser_arnoldi powser_arnoldi.c -lflint -lmpfr -lgmp -lpthread -lm")

open("in.gz.b64", "w").write(PAYLOAD)
open("label6-carnoldi-p100.txt", "wb").write(
    gzip.decompress(base64.b64decode(PAYLOAD)))
print("MARKER input bytes", os.path.getsize("label6-carnoldi-p100.txt"), flush=True)

t0 = time.time()
r = sp.run("./powser_arnoldi label6-carnoldi-p100.txt label6-out-p100.m",
           shell=True, capture_output=True, text=True)
print(f"MARKER solver exit={r.returncode} {time.time()-t0:.0f}s", flush=True)
print("MARKER solver stdout tail:", r.stdout[-1500:].replace(chr(10), " | "), flush=True)
if r.returncode != 0:
    print(r.stderr[-4000:], file=sys.stderr); sys.exit(2)
out = open("label6-out-p100.m", "rb").read()
assert out and b"[*" in out[:100], "outfile not Magma data"
print("MARKER out bytes", len(out), flush=True)
b64o = base64.b64encode(gzip.compress(out, 9)).decode()
print("MARKER FILE BEGIN label6-out-p100.m.gz.b64", flush=True)
for i in range(0, len(b64o), 4000):
    print(b64o[i:i+4000])
print("MARKER FILE END", flush=True)

